import unittest
from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("1001", "Thistle", "Bram", "A")


def mark(num, status="absent", pupil_id="1001"):
    return Mark(pupil_id, date(2026, 9, num), status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_sorted_dates(self):
        marks = [mark(9), mark(3), mark(5, "present")]
        self.assertEqual(
            build_notice(PUPIL, marks),
            "Bram Thistle missed 2 days of school.\n"
            "Dates absent: 2026-09-03, 2026-09-09"
        )

    def test_single_day_is_singular(self):
        text = build_notice(PUPIL, [mark(4)])
        self.assertIn("missed 1 day of school", text)

    def test_other_status_is_ignored(self):
        marks = [mark(4), mark(5, "late"),
            mark(6, "excused")]
        text = build_notice(PUPIL, marks)
        self.assertIn("missed 1 day", text)

    def test_foreign_mark_is_rejected(self):
        marks = [mark(4), mark(5, pupil_id="2002")]
        with self.assertRaises(ValueError):
            build_notice(PUPIL, marks)

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(4, "present")])

    def test_empty_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [])
